{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 취약계층 반려동물 진료비 지원 대상 여부(기초생활수급자, 동물 미등록)",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제25조의2 제4항에 따르면, 진료비 등 경비를 지원받으려면 시에 주민등록을 두고 있어야 하고 동물정보시스템에 등록된 해당 반려동물의 소유자등이어야 한다. 질문자는 동물등록을 하지 않았으므로 이 요건을 충족하지 못한다. 따라서 취약계층에 해당하더라도 동물등록이 되어 있지 않으면 이 조례에 따른 진료비 지원 대상이 될 수 없다.",
          "b_ids": "동물보호:제25조의2제4항, 동물보호:제25조의2제2항제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
